window.RP_SESSION={"id":"S-5c80169e53df","messages":[{"id":"RP-0270349","time":"2026-09-11T22:24:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"크 아 악 퇴 근 이 다","characters":["P-7ba611cf90be"]},{"id":"RP-0270350","time":"2026-09-11T22:25:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"하루종일 활자와 씨름하던 시야가 탁 트인 밤 하늘을 보니 자유를 만끽합니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0270351","time":"2026-09-11T22:26:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"오랜만에 도끼질이나 할까요?\n\n\"...음.\"\n\n누군가 해놨네요.","characters":["P-7ba611cf90be"]},{"id":"RP-0270352","time":"2026-09-11T22:26:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그냥 냅다 그루터기 자리에 앉았습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0270353","time":"2026-09-11T22:28:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"담배를....\n\n이런.\n\n에스텔이 넣어둔 사탕을 잘못 챙겨왔네요.","characters":["P-7ba611cf90be"]},{"id":"RP-0270354","time":"2026-09-11T22:33:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 토르번님, 거기서 무얼하고 계십니까? \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270355","time":"2026-09-11T22:33:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"음?\"\n\n\"시안 형씨인가.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270356","time":"2026-09-11T22:33:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"원래 여기가 내 전용석이었는데, 누가 내 할 일을 해놓았구만. 나는 서류나 하라는 건가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270357","time":"2026-09-11T22:34:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 이제 공대장이시니, 서류작업도 그만큼 중요한 일 아니시겠습니까. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270358","time":"2026-09-11T22:35:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"분명 스텔라 양이 나한테 공격대장을 맡긴 이유는 낭만과 모험이었는데 말일세...\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270359","time":"2026-09-11T22:35:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"서류에 짓눌리다보니 왠지 자리를 비우기가 미안해지고 있다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270360","time":"2026-09-11T22:36:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"내가 며칠 안하면 스텔라 양이나 션 형씨가 하게 될 양이니 말일세.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270361","time":"2026-09-11T22:36:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 길드원분들의 낭만과 모험을 위해서, 누군가가 이런 작업을 처리하게 되는것 아니겠습니까. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270362","time":"2026-09-11T22:36:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그만큼, 중요한 일이니까요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270363","time":"2026-09-11T22:37:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...말은 청산 유수구만.\"\n\n킬킬 웃으며 사탕을 깨물어 소리내었습니다.\n\n\"자네는? 무슨 일로 왔는가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270364","time":"2026-09-11T22:38:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"  ...ㅡ저야, 뭐, 항상 그렇듯이, 임무가 없으면, 훈련하는 시간이 길지요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270365","time":"2026-09-11T22:39:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그러다, 토르번님이 보여서, 와봤습니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270366","time":"2026-09-11T22:40:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"훈련하러 가는 길이었구만? 요즘 신입들이 열심히더라고.\"\n\n\"기왕 온 김에 얘기나 나누다가 가지? 싫음 관두고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270367","time":"2026-09-11T22:40:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그렇게 말하시면, 거부했을 때가 두렵군요. 좋습니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270368","time":"2026-09-11T22:41:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...그나저나, 저도 이제 정식 길드원입니다만. 아직 신입취급입니까? \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270369","time":"2026-09-11T22:41:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"ㅋㅋ거부하면 며칠 삐치는 거 말고 더 있겠나.\"\n\n\"아니. 자네가 그렇다는 게 아니라, 요즘 추세가 그렇다는 거지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270370","time":"2026-09-11T22:42:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 아아, 그런 이야기로군요. 공대장님이 삐지신다는게, 더 무서운 이야기 아니겠습니까? \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270371","time":"2026-09-11T22:44:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"내가 삐쳐봤자 3분 정도 밖에 안간다네.\"\n\n\"오래된 길드원들은 나를 완전 동네북 취급했었다고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270372","time":"2026-09-11T22:45:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 아까, 본인입으로 며칠이라고 하시지않으셨습니까? 어떤쪽을 믿어야할지 모르겠군요. \"\n\n시안도, 앉았습니다.","characters":["P-77d4478f4f51"]},{"id":"RP-0270373","time":"2026-09-11T22:46:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"며칠동안 3분씩 생각난다네.\"\n\n킬킬.","characters":["P-7ba611cf90be"]},{"id":"RP-0270374","time":"2026-09-11T22:46:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"뭐가 됐건 농일세. 요즘 힘든 일은 없고?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270375","time":"2026-09-11T22:47:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n힘든일, 이라면 있다.\n다만, 바로 어제, 약속치 않았는가.\n\n\" ...토르번님께선, 사이먼님의 소식, 들으셨습니까? \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270376","time":"2026-09-11T22:47:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...사이먼 형씨? 요즘 방에서 안나온다고들 그러던데. 어디 아픈가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270377","time":"2026-09-11T22:48:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"나이에 안 맞게 속늙어가지고 건강이 걱정된단 말이지.\"\n\n너털거리며 웃었습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0270378","time":"2026-09-11T22:48:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...잡혔던 이가 이야기했다고 하더군요. 사이먼님에 가까운 인상착의를 한분을, 죽였다고. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270379","time":"2026-09-11T22:49:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 또한, 션님께, 사이먼님이 가지고 다니시던 묵주가 부숴진채, 배달되었다고 합니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270380","time":"2026-09-11T22:49:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...전부, 사이먼님이 아닐수도 있고, 사이먼님의 것도 아닐지도 모르지만요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270381","time":"2026-09-11T22:50:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"초승달처럼 웃던 눈이, 잠시 굳었다가.\n\n두어번 끔뻑끔뻑.\n\n\"...\"\n\n농담이지?라는 말이 입밖으로 나오려다가 들어갔습니다.\n\n자세를 고쳐앉고는.\n\n\"...그래? 그랬구만....\"\n\n무표정하게 이마를 긁적였습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0270382","time":"2026-09-11T22:51:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...예, 션님의 출발 전에 션님에게 들은 내용입니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270383","time":"2026-09-11T22:54:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...장례식도 못 치루겠구만. 조금은 미련도 가지게 되고....\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270384","time":"2026-09-11T22:55:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n시안은, 무언가 입을 다물다가.\n\n\" ...너무, 분위기가 무거워졌군요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270385","time":"2026-09-11T22:56:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...그래도, 길드원분들에게 전해야할 얘기라고, 생각했습니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270386","time":"2026-09-11T22:57:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"잘했네. 고생했어.\"\n\n\"말하기 무거웠을텐데 잘 말해줬다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270387","time":"2026-09-11T22:58:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...전해야 할 얘기일테니까요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270388","time":"2026-09-11T22:58:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...어려운 이야기이기도 하지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270389","time":"2026-09-11T22:58:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"자네는 괜찮은가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270390","time":"2026-09-11T22:58:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...그러는, 토르번님이야 말로, 고민있으십니까? \"\n\n시안은, 이야기를 돌릴려하다..","characters":["P-77d4478f4f51"]},{"id":"RP-0270391","time":"2026-09-11T22:59:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"괜찮냐는 얘기에.\n\n\" ...괜찮아질려, 노력하고있습니다. C","characters":["P-77d4478f4f51"]},{"id":"RP-0270392","time":"2026-09-11T23:00:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그거 다행일세.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270393","time":"2026-09-11T23:00:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"괜찮지도 말고, 괜찮지 않지도 말게.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270394","time":"2026-09-11T23:00:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"괜찮아지려고 노력하는 거. 그거면 된 거야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270395","time":"2026-09-11T23:00:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...감사합니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270396","time":"2026-09-11T23:02:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"흠. 나도 이제 괜찮아지려고 노력하려고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270397","time":"2026-09-11T23:02:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"같이 노력하지 뭐.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270398","time":"2026-09-11T23:02:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"안타깝게 됐구만.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270399","time":"2026-09-11T23:04:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...예, 그래야겠네요. 안타까운 일이지요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270400","time":"2026-09-11T23:05:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"둘이 제법 친했는가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270401","time":"2026-09-11T23:06:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"친했는가, 그것은 아니라고 생각한다.\n\n\" ...그것은 아니었습니다, 같이 임무를 한번 가긴했습니다만. 그뒤로도, 몇번 만나뵜던 정도입니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270402","time":"2026-09-11T23:08:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...그래?\"\n\n\"실은 말일세. 나도 그렇게 친하진 않았어.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270403","time":"2026-09-11T23:08:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"헌데 그 때문에 더 아쉽구만.\"\n\n\"있을 때 좀 더 잘 할 걸.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270404","time":"2026-09-11T23:09:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...옳은 말씀이시군요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270405","time":"2026-09-11T23:09:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 언제나, 잃은 뒤에야...후회하게 되는 것 같습니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270406","time":"2026-09-11T23:10:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"사람이 모두를 당장 내일 떠나보낼 것처럼 사랑할 수 있으면 얼마나 좋을까.\"\n\n\"어렵지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270407","time":"2026-09-11T23:11:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...토르번님이 저와 동갑으로 알고 계신데, 저보다 훨씬, 어른스러우시군요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270408","time":"2026-09-11T23:12:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...그래? 아닐 걸.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270409","time":"2026-09-11T23:12:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그런 척을 잘하는 걸지도 몰라.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270410","time":"2026-09-11T23:13:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...그럴지도, 모르겠군요. 저는, 그것조차 잘 못하고 있지만 말입니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270411","time":"2026-09-11T23:14:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"자리가 사람을 만든대.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270412","time":"2026-09-11T23:14:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그러니까... 요 짐을 내려놓으면 자네와 나는 똑같을지도 모른다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270413","time":"2026-09-11T23:15:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n그것에는, 공감치 못했습니다. 자리가 무거워, 도망쳤던 자신은요.","characters":["P-77d4478f4f51"]},{"id":"RP-0270414","time":"2026-09-11T23:17:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"음, 나는 도망치고 싶어지면 모험을 갔었다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270415","time":"2026-09-11T23:17:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"사실 자주 짐을 내려놓고 싶어서, 자주 갔었지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270416","time":"2026-09-11T23:17:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"요즘은 영 시원치 않은 게, 가끔 가더라도 신입들이 대장님 대장님 노래를 불러서 말이야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270417","time":"2026-09-11T23:18:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...그건, 의외시군요 \"\n\n\" 대장님소리, 듣기 싫으십니까? \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270418","time":"2026-09-11T23:19:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"때에 따라선?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270419","time":"2026-09-11T23:19:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"가끔은 무겁고.\"\n\n\"가끔은 날카로운 이름이지 않은가.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270420","time":"2026-09-11T23:19:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그건...확실히 그렇지요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270421","time":"2026-09-11T23:20:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"싫다는 얘기는 아닐세.\"\n\n\"가끔은 책임은 다 잊어버리고 무모하게 뛰어들고 싶다는 거야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270422","time":"2026-09-11T23:21:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"왠지 그렇거든. 무슨 일이 생기면 전부 내 책임인 것 같고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270423","time":"2026-09-11T23:21:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...이해될  것, 같기도하군요. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270424","time":"2026-09-11T23:22:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"와다다","characters":["P-d8e7afee7c51"]},{"id":"RP-0270425","time":"2026-09-11T23:22:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-d8e7afee7c51"]},{"id":"RP-0270426","time":"2026-09-11T23:22:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"토르번씨, 신입!\"","characters":["P-d8e7afee7c51"]},{"id":"RP-0270427","time":"2026-09-11T23:22:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"조금 오만한 이야기일지도 모르겠네.\"\n\n\"왜냐하면 죽음을 각오하고 함께 싸우고자 하는 이들의 맹세를 무시하기도 하니까.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270428","time":"2026-09-11T23:22:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"어...?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270429","time":"2026-09-11T23:22:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 반갑습니다. 루체님. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270434","time":"2026-09-11T23:23:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"신입!\"","characters":["P-d8e7afee7c51"]},{"id":"RP-0270435","time":"2026-09-11T23:23:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...이런. 호랑이도 제말하면 온다더니...\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270436","time":"2026-09-11T23:23:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"토르번 옷깃을 잡습니다","characters":["P-d8e7afee7c51"]},{"id":"RP-0270437","time":"2026-09-11T23:23:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 신입분이, 오셨습니까? \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270438","time":"2026-09-11T23:24:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"신입~~\"","characters":["P-d8e7afee7c51"]},{"id":"RP-0270439","time":"2026-09-11T23:24:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"질질","characters":["P-d8e7afee7c51"]},{"id":"RP-0270440","time":"2026-09-11T23:24:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"응 안끌려","characters":["P-d8e7afee7c51"]},{"id":"RP-0270441","time":"2026-09-11T23:24:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"시안 형씨. 나는 자네랑 이야기 하고 싶은 게 많거든.\"\n\n\"친구처럼 지내세나. 음... 어려울지도 모르겠지만.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270442","time":"2026-09-11T23:24:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"알았어 알았어. 얼른 가세나.\"\n\n라며 루체의 이끌림을 따라 갑니다.\n\n\"좋은 밤 되게.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0270443","time":"2026-09-11T23:25:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"질질질","characters":["P-d8e7afee7c51"]},{"id":"RP-0270444","time":"2026-09-11T23:25:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"3번방으로..,>","characters":["P-d8e7afee7c51"]},{"id":"RP-0270445","time":"2026-09-11T23:25:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ....제게 관심이 있으실줄은 몰랐습니다. 예, 좋습니다. \"\n\n\" 친구처럼, 예. 좋습니다. \"","characters":["P-77d4478f4f51"]},{"id":"RP-0270446","time":"2026-09-11T23:25:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"라고하며, 시안역시ㅡ, 궁금하였기에, 그들을 따라갔다.","characters":["P-77d4478f4f51"]},{"id":"RP-0270447","time":"2026-09-11T23:25:00+09:00","room":"RP","name":"시안 던 브링어","profile":"GM","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-77d4478f4f51"]}]};
